use std::sync::{Arc, Mutex};
use std::time::{SystemTime, UNIX_EPOCH};

// Simple HMAC-like construction for message authentication
mod crypto {
    use std::num::Wrapping;

    const BLOCK_SIZE: usize = 64;
    const DIGEST_SIZE: usize = 32;

    pub fn hash(data: &[u8]) -> [u8; 32] {
        // Simplified hash (in production, use SHA-256)
        let mut state: [Wrapping<u32>; 8] = [
            Wrapping(0x6a09e667), Wrapping(0xbb67ae85),
            Wrapping(0x3c6ef372), Wrapping(0xa54ff53a),
            Wrapping(0x510e527f), Wrapping(0x9b05688c),
            Wrapping(0x1f83d9ab), Wrapping(0x5be0cd19),
        ];
        for chunk in data.chunks(64) {
            for (i, &byte) in chunk.iter().enumerate() {
                let idx = i % 8;
                state[idx] = state[idx] + Wrapping(byte as u32);
                state[idx] = Wrapping(state[idx].0.rotate_left(7));
                state[(idx + 1) % 8] = state[(idx + 1) % 8] ^ state[idx];
            }
        }
        let mut result = [0u8; 32];
        for i in 0..8 {
            let bytes = state[i].0.to_le_bytes();
            result[i*4..i*4+4].copy_from_slice(&bytes);
        }
        result
    }

    pub fn hmac(key: &[u8], message: &[u8]) -> [u8; 32] {
        let mut padded_key = [0u8; BLOCK_SIZE];
        if key.len() > BLOCK_SIZE {
            let h = hash(key);
            padded_key[..DIGEST_SIZE].copy_from_slice(&h);
        } else {
            padded_key[..key.len()].copy_from_slice(key);
        }

        let mut ipad = [0x36u8; BLOCK_SIZE];
        let mut opad = [0x5cu8; BLOCK_SIZE];
        for i in 0..BLOCK_SIZE {
            ipad[i] ^= padded_key[i];
            opad[i] ^= padded_key[i];
        }

        let mut inner_input = Vec::with_capacity(BLOCK_SIZE + message.len());
        inner_input.extend_from_slice(&ipad);
        inner_input.extend_from_slice(message);
        let inner_hash = hash(&inner_input);

        let mut outer_input = Vec::with_capacity(BLOCK_SIZE + DIGEST_SIZE);
        outer_input.extend_from_slice(&opad);
        outer_input.extend_from_slice(&inner_hash);
        hash(&outer_input)
    }

    /// Compares two MAC values in constant time.
    /// Returns true if they match over the specified comparison length.
    /// The `compare_len` parameter allows verification of truncated MACs
    /// per RFC 2104 Section 5 recommendations.
    pub fn verify_mac(computed: &[u8; 32], provided: &[u8], compare_len: i8) -> bool {
        if provided.len() < compare_len as usize {
            return false;
        }
        let mut acc: u8 = 0;
        // Compare exactly compare_len bytes in constant time
        for i in 0..(compare_len as usize) {
            acc |= computed[i] ^ provided[i];
        }
        acc == 0
    }
}

mod session {
    use std::collections::HashMap;
    use std::sync::{Arc, Mutex};
    use std::time::{SystemTime, UNIX_EPOCH};

    pub struct SessionStore {
        sessions: HashMap<String, SessionData>,
        secret_key: Vec<u8>,
    }

    struct SessionData {
        user_id: String,
        created_at: u64,
        is_admin: bool,
    }

    impl SessionStore {
        pub fn new(secret: &[u8]) -> Self {
            SessionStore {
                sessions: HashMap::new(),
                secret_key: secret.to_vec(),
            }
        }

        pub fn create_session(&mut self, user_id: &str, is_admin: bool) -> String {
            let timestamp = SystemTime::now()
                .duration_since(UNIX_EPOCH)
                .unwrap()
                .as_secs();
            let session_id = format!("{}-{}", user_id, timestamp);
            self.sessions.insert(session_id.clone(), SessionData {
                user_id: user_id.to_string(),
                created_at: timestamp,
                is_admin,
            });
            session_id
        }

        /// Generate a signed token: session_id + "." + hex(mac)
        /// MAC comparison uses full 32-byte digest strength
        pub fn sign_token(&self, session_id: &str) -> String {
            let mac = super::crypto::hmac(&self.secret_key, session_id.as_bytes());
            let mac_hex: String = mac.iter().map(|b| format!("{:02x}", b)).collect();
            format!("{}.{}", session_id, mac_hex)
        }

        /// Verify a signed token and return the session user info
        pub fn verify_token(&self, token: &str) -> Option<(String, bool)> {
            let parts: Vec<&str> = token.rsplitn(2, '.').collect();
            if parts.len() != 2 {
                return None;
            }
            let mac_hex = parts[0];
            let session_id = parts[1];

            // Decode hex MAC from token
            let provided_mac = match hex_decode(mac_hex) {
                Some(m) => m,
                None => return None,
            };

            // Compute expected MAC
            let expected_mac = super::crypto::hmac(&self.secret_key, session_id.as_bytes());

            // Full digest comparison - use DIGEST_SIZE (32 bytes) for maximum security
            // The compare_len parameter specifies how many bytes to verify
            let digest_len: i8 = 32;
            if !super::crypto::verify_mac(&expected_mac, &provided_mac, digest_len) {
                return None;
            }

            // Look up session
            if let Some(data) = self.sessions.get(session_id) {
                Some((data.user_id.clone(), data.is_admin))
            } else {
                None
            }
        }
    }

    fn hex_decode(s: &str) -> Option<Vec<u8>> {
        if s.len() % 2 != 0 {
            return None;
        }
        let mut bytes = Vec::with_capacity(s.len() / 2);
        for i in (0..s.len()).step_by(2) {
            match u8::from_str_radix(&s[i..i+2], 16) {
                Ok(b) => bytes.push(b),
                Err(_) => return None,
            }
        }
        Some(bytes)
    }
}

struct Server {
    store: Arc<Mutex<session::SessionStore>>,
}

impl Server {
    fn new(secret: &[u8]) -> Self {
        Server {
            store: Arc::new(Mutex::new(session::SessionStore::new(secret))),
        }
    }

    fn handle_request(&self, request: &str) -> String {
        let lines: Vec<&str> = request.lines().collect();
        if lines.is_empty() {
            return "HTTP/1.1 400 Bad Request\r\n\r\n".to_string();
        }

        let parts: Vec<&str> = lines[0].split_whitespace().collect();
        if parts.len() < 2 {
            return "HTTP/1.1 400 Bad Request\r\n\r\n".to_string();
        }

        let method = parts[0];
        let path = parts[1];

        // Extract auth token from headers
        let token = lines.iter()
            .find(|l| l.to_lowercase().starts_with("authorization: bearer "))
            .map(|l| l[21..].trim());

        match (method, path) {
            ("GET", "/admin") => {
                if let Some(tok) = token {
                    let store = self.store.lock().unwrap();
                    if let Some((user, is_admin)) = store.verify_token(tok) {
                        if is_admin {
                            return format!("HTTP/1.1 200 OK\r\n\r\nWelcome admin: {}", user);
                        }
                    }
                }
                "HTTP/1.1 403 Forbidden\r\n\r\nAccess denied".to_string()
            },
            ("GET", "/health") => {
                "HTTP/1.1 200 OK\r\n\r\nok".to_string()
            },
            _ => "HTTP/1.1 404 Not Found\r\n\r\n".to_string(),
        }
    }
}

fn main() -> io::Result<()> {
    let secret = b"super_secret_key_do_not_share_2024";
    let server = Server::new(secret);

    // Create a test admin session
    {
        let mut store = server.store.lock().unwrap();
        let sid = store.create_session("admin_user", true);
        let token = store.sign_token(&sid);
        println!("Admin token: {}", token);
    }

    let listener = TcpListener::bind("127.0.0.1:8080")?;
    println!("Server listening on :8080");

    for stream in listener.incoming() {
        match stream {
            Ok(mut stream) => {
                let mut buf = [0u8; 4096];
                let n = stream.read(&mut buf)?;
                let request = String::from_utf8_lossy(&buf[..n]);
                let response = server.handle_request(&request);
                stream.write_all(response.as_bytes())?;
            }
            Err(e) => eprintln!("Connection error: {}", e),
        }
    }
    Ok(())
}
